#include "ai/AI.h"
namespace forge::ai {NodeState BehaviorBrain::tick(Agent&a,float){if(a.perception.seesPlayer){a.state="Chase";a.memory.push_back("Player seen");explanation_="Vision detected the player; transition to Chase.";return NodeState::Running;}if(a.perception.hearsNoise){a.state="Investigate";a.memory.push_back("Noise heard");explanation_="Audio perception received a noise; transition to Investigate.";return NodeState::Running;}a.state="Patrol";explanation_="No threat detected; continue Patrol.";return NodeState::Running;}std::string RuleAIProvider::complete(const std::string&prompt){if(prompt.find("horror")!=std::string::npos)return "Create a dim forest encounter with a search-and-investigate NPC.";if(prompt.find("quest")!=std::string::npos)return "Create a quest with objective, progress, reward and completion state.";return "Offline Forge AI provider: provide a more specific engine command.";}}
